import geometry from './belortzioak-geometry.json';

/**
 * Belortzioak: the course's labelled figures (an arrow on a structure → its name), from the skin's
 * anatomy to the digestive system. Names follow the corrected legends of the figure set; a sub-item
 * ("2. II.a") is written out in full so it can stand alone in a question.
 *
 * Geometry (where each number sat and the point its arrow touches) is generated by
 * `scripts/belortzioak/extract.py` into `belortzioak-geometry.json`; the figures themselves into
 * `public/belortzioak-irudiak/`.
 * A number whose name is not given here (crossed out in the legend, or "not visible") is left out.
 * Where the legend was corrected by hand, the hand-written name wins (the printed one is accepted
 * when typed); labels that exist only in handwriting are under `hand`, keyed by the id the
 * extractor gives them.
 */

export type BelSystem = 'azala' | 'blastoak' | 'kardio' | 'arnas' | 'digestio';

export const BEL_SYSTEMS: { id: BelSystem; title: string; short: string }[] = [
  { id: 'azala', title: 'Kanpo-itxura (azal-anatomia)', short: 'Kanpo-itxura' },
  { id: 'blastoak', title: 'Blastoak', short: 'Blastoak' },
  { id: 'kardio', title: 'Sistema kardiobaskularra', short: 'Kardiobaskularra' },
  { id: 'arnas', title: 'Arnas sistema eta linfa-sistema', short: 'Arnas sistema' },
  { id: 'digestio', title: 'Digestio-aparatua', short: 'Digestio-aparatua' },
];

type Pt = [number, number];

export interface BelItem {
  /** `${plate}:${n}` (or the hand-written label's id) — stable across sessions (progress is stored by it). */
  key: string;
  n: number;
  /** What the figure shows for it: the printed number, or what was written by hand ("9.2", "10a"). */
  tag: string;
  /** A label written in red pen (a numbering of its own, next to the printed one). */
  ink?: 'red';
  name: string;
  /** The legend heading it hangs from ("Faringe-arkuak"), shown above the name. */
  group?: string;
  /** Other answers accepted when typed (a name that lists two things accepts either). */
  accept?: string[];
  /** Where the number sat, as fractions of the figure (0..1). */
  label: Pt;
  /** The point(s) its arrow touches; a number without an arrow sits on its structure (= label). */
  targets: Pt[];
  /** The number written again by hand on its structure (also among `targets`): drawn there, no line. */
  marks: { at: Pt; tag?: string }[];
  /** Whether the figure drew an arrow (false: the number was printed on the structure itself). */
  arrow: boolean;
  /** Spotlight radius per target, as a fraction of the figure's longer side. */
  r: number[];
}

export interface BelPlate {
  id: string;
  system: BelSystem;
  title: string;
  /** Which of the three embryos of the set, or the kind of view. */
  sub: string;
  /** Figure size in pixels (its aspect ratio). */
  size: [number, number];
  items: BelItem[];
}

interface Entry {
  name: string;
  group?: string;
  accept?: string[];
}
type Legend = Record<number, string | Entry>;

