interface Geo {
  size: [number, number];
  items: { n: number; id?: string; tag?: string; ink?: 'red'; label: Pt; targets: Pt[]; marks?: { at: Pt; tag?: string }[]; r: number[] }[];
}
const GEO = geometry as unknown as Record<string, Geo>;

export const BEL_PLATES: BelPlate[] = DEFS.map((d) => {
  const g = GEO[d.id];
  const items = g.items.flatMap((it): BelItem[] => {
    const raw = d.hand?.[it.id ?? String(it.n)] ?? (it.id ? undefined : d.legend[it.n]);
    if (!raw) return [];
    const e: Entry = typeof raw === 'string' ? { name: raw } : raw;
    const targets = it.targets.length ? it.targets : [it.label];
    return [{ key: `${d.id}:${it.id ?? it.n}`, n: it.n, tag: it.tag ?? String(it.n), ink: it.ink, name: e.name, group: e.group, accept: e.accept, label: it.label, targets, marks: it.marks ?? [], arrow: it.targets.length > 0, r: it.r.length ? it.r : [0.05] }];
  });
  return { id: d.id, system: d.system, title: d.title, sub: d.sub, size: g.size, items };
});

export const BEL_ITEMS: { plate: BelPlate; item: BelItem }[] = BEL_PLATES.flatMap((plate) => plate.items.map((item) => ({ plate, item })));

/** Lower case, no accents, Roman ordinals as digits, no punctuation: what two spellings share. */
export function normalizeName(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\b(vi|iv|v|iii|ii|i)\b\.?/g, (m) => String({ i: 1, ii: 2, iii: 3, iv: 4, v: 5, vi: 6 }[m.replace('.', '') as 'i']))
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** The same structure in other figures: the name without what is in brackets, compared loosely. */
export const sameKey = (name: string) => normalizeName(name.replace(/\(.*?\)/g, '').replace(/:.*$/, ''));

const levenshtein = (a: string, b: string) => {
  const row = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = row[0];
    row[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = row[j];
      row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return row[b.length];
};

/** Typos forgiven in one word: none in short words, one in middling ones, two in long ones. */
const slack = (n: number) => (n <= 4 ? 0 : n <= 8 ? 1 : 2);

/**
 * Whether a typed answer names the item. Accents, case, hyphens, Roman/Arabic ordinals and word order
 * are free; each word may carry a small typo. Words are compared one by one, so "Goiko" never passes
 * for "Beheko" just because the rest of a long name matches.
 */
export function matchesName(typed: string, item: Pick<BelItem, 'name' | 'accept'>): boolean {
  const t = normalizeName(typed);
  if (t.length < 3) return false;
  const forms = [item.name, item.name.replace(/\(.*?\)/g, ''), ...(item.accept ?? [])].map(normalizeName).filter(Boolean);
  const tw = t.split(' ');
  return forms.some((f) => {
    const fw = f.split(' ');
    if (fw.length === tw.length) {
      const left = [...tw];
      const all = fw.every((w) => {
        const i = left.findIndex((x) => levenshtein(x, w) <= slack(w.length));
        if (i < 0) return false;
        left.splice(i, 1);
        return true;
      });
      if (all) return true;
    }
    // Words run together or split differently ("zilborarteriak"): compare without spaces, strictly,
    // and ordinals must agree exactly (2. is never 3.).
    if (fw.length === tw.length || t.replace(/\D/g, '') !== f.replace(/\D/g, '')) return false;
    const a = t.replace(/ /g, '');
    const b = f.replace(/ /g, '');
    return levenshtein(a, b) <= Math.min(2, slack(b.length));
  });
}
